    return ManualCompactionOutcome(
      ran: result.passes > 0,
      passes: result.passes,
      before: result.before,
      after: result.after,
      failure: result.failure,
      exhausted: result.exhausted,
      underWindow: _underWindow(result.after),
    );
  }
